use super::*;
use crate::{DslValue,Number,retained_clone::RetainedCloneSource,source_fixture::{Wallet,receive,post_step,close_owned,denials}};
fn bank()->Wallet{let f:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::fixture_text!("../../🌳️value/👥️tuple/🧪️tests/🧫️fixtures/📐️.json")).unwrap();Wallet::from_profile(&f["stock"])}
fn source(v:DslValue,bank:&mut Wallet)->RetainedCloneSource<DslValue>{crate::source_fixture::capture(v,bank,|w|w.loan(1,4096),|w,p,work,h,g|w.post(p,work,g,h))}
fn advance<T,R:NativeReceiver<DslValue,T>>(r:&mut R,s:crate::retained_clone::RetainedCloneRef<'_,DslValue>,c:&mut NativeDecodeControl<'_>,g:RetainedCloneGrant,bank:&mut Wallet)->Result<RetainedCloneStep,crate::OriginalReceivingPrimary>{let(t,h)=crate::observe_retirement_allocations(||receive(c,g,bank.work_loan(1),|c|r.advance(s,c,4096,g)));post_step(bank,t,g,h,crate::OriginalReceivingPrimary::retained_progress)}
fn close<T,R:NativeReceiver<DslValue,T>>(r:&mut R,bank:&mut Wallet){r.begin_close();for _ in 0..100000{if r.terminal_is_empty(){return}let d=r.close_demands(4096).unwrap();let g=bank.loan(1,4096);for g in denials(g,d){let(t,h)=crate::observe_retirement_allocations(||r.close_step(g));assert_eq!(t.work,0);assert_eq!(t.result.unwrap().progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(r.close_demands(4096).unwrap(),d);}let(t,h)=crate::observe_retirement_allocations(||r.close_step(g));post_step(bank,t,g,h,ValueError::retained_progress).unwrap();}panic!("tuple receiver did not close")}
fn original_prefixes<T:NativeReceive<DslValue>>(input:impl Fn()->DslValue,check:impl Fn(&T)){let mut finished=0;for cut in 0..500{let mut bank=bank();let original=source(input(),&mut bank);let foreign=source(input(),&mut bank);let(mut r,h)=crate::observe_retirement_allocations(T::receiver);assert_eq!(h,(0,0));let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<24,&mut callback);let mut turns=0;for _ in 0..cut{if r.output_ready(){break}let d=r.demands(original.borrow(),4096).unwrap();let g=bank.loan(1,4096);for denied in denials(g,d){let(t,h)=crate::observe_retirement_allocations(||receive(&mut control,denied,bank.work_loan(1),|c|r.advance(original.borrow(),c,4096,denied)));assert_eq!(t.work,0);assert_eq!(t.result.unwrap().progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(r.demands(original.borrow(),4096).unwrap(),d);}advance(&mut r,original.borrow(),&mut control,g,&mut bank).unwrap();assert!(r.demands(foreign.borrow(),4096).is_err());turns+=1;}if r.output_ready(){let d=r.take_demand().unwrap();let g=bank.loan(1,4096);for g in denials(g,d){let(t,h)=crate::observe_retirement_allocations(||r.take(g));assert_eq!(t.work,0);assert!(t.result.unwrap().is_none());assert_eq!(h,(0,0));}let(t,h)=crate::observe_retirement_allocations(||r.take(g));let(v,p)=t.result.unwrap().unwrap();bank.post(p,t.work,g,h);check(&v);close_owned(v,&mut bank,4096,100000);finished=turns;}close(&mut r,&mut bank);close_owned(original,&mut bank,4096,100000);close_owned(foreign,&mut bank,4096,100000);if finished>0{break}}assert!(finished>0);}
#[test]fn original_heterogeneous_tuple_receiving_preserves_every_paid_prefix_and_wire_kind(){
 original_prefixes::<(u32,String)>(||DslValue::Array(vec![DslValue::Number(Number::UInt(17)),DslValue::String("β".into())]),|v|assert_eq!(v,&(17,"β".into())));
 original_prefixes::<(u16,u8,u8)>(||DslValue::Array(vec![DslValue::Number(Number::UInt(2024)),DslValue::Number(Number::UInt(2)),DslValue::Number(Number::UInt(29))]),|v|assert_eq!(v,&(2024,2,29)));
 for count in [1,3]{let mut bank=bank();let original=source(DslValue::Array((0..count).map(|_|DslValue::Number(Number::UInt(17))).collect()),&mut bank);let mut r=<(u32,String)as NativeReceive<DslValue>>::receiver();let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<20,&mut callback);let mut refused=false;for _ in 0..500{if r.output_ready(){break}let g=bank.loan(1,4096);if advance(&mut r,original.borrow(),&mut control,g,&mut bank).is_err(){refused=true;break}}assert!(refused);assert!(!r.output_ready());close(&mut r,&mut bank);close_owned(original,&mut bank,4096,100000);}
}
